{{ config(materialized='table') }}

with
quarantined as (
    select
        gp_name_lookup_key,
        gp_business_key,
        gp_entity_count,
        violation_00,
        violation_01,
        violation_02
    from {{ ref("investment__gp_name_index__checked_post") }}
),
violations as (
    select
        'gp_name_lookup_key_not_null' as rule_name,
        gp_name_lookup_key,
        gp_business_key,
        gp_entity_count
    from quarantined
    where violation_00

    union all

    select
        'gp_name_lookup_key_unique' as rule_name,
        gp_name_lookup_key,
        gp_business_key,
        gp_entity_count
    from quarantined
    where violation_01

    union all

    select
        'gp_entity_count_range' as rule_name,
        gp_name_lookup_key,
        gp_business_key,
        gp_entity_count
    from quarantined
    where violation_02
)

select
    rule_name,
    gp_name_lookup_key,
    gp_business_key,
    gp_entity_count
from violations
